const res = await fetch('http://127.0.0.1:8787/v1/chat/completions', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ model: 'auto', messages: [{ role: 'user', content: '你好' }] }),
});
const d = await res.json();
console.log(d.choices?.[0]?.message?.content);

examples.multimodal:
// 看图：content 是数组，text 和 image_url 都要带
{
  "model": "glm-4v-flash",
  "messages": [{
    "role": "user",
    "content": [
      { "type": "text", "text": "这张图里有什么？" },
      { "type": "image_url", "image_url": { "url": "data:image/png;base64,iVBORw0KGgo..." } }
    ]
  }]
}
// url 也可以直接填 https 图片地址；base64 更稳（外链有时会被拒）。

examples.batch:
// 批量处理：控制并发 4 路，别一次开几十条（免费渠道有速率限制）
// 实测 5 路并发稳定，超过就会被限流
for (const item of items) {
  await callGateway({ model: 'THUDM/GLM-4-9B-0414', messages: [{ role: 'user', content: item.q }] });
}
